mapper.select:
SELECT s.id AS id, s.user_id AS userId, s.student_no AS studentNo, u.real_name AS realName, u.avatar AS avatar, u.gender AS gender, d1.name AS major, d2.name AS clazz, s.entry_year AS entryYear FROM students s LEFT JOIN user u ON s.user_id = u.id LEFT JOIN sys_dept d1 ON s.major_id = d1.id LEFT JOIN sys_dept d2 ON s.class_id = d2.id
AND s.university_id = #{universityId}
AND s.college_id = #{collegeId}
AND s.student_no LIKE concat('%', #{studentNo}, '%')
AND s.major_id = #{majorId}
AND s.class_id = #{classId}
AND s.entry_year = #{entryYear}
AND s.bind_status = #{bindStatus}
ORDER BY id DESC

select s.id, s.user_id as userId, s.student_no as studentNo, s.university_id as universityId, u.name as universityName, s.college_id as collegeId, c.name as collegeName, s.major_id as majorId, m.name as majorName, s.class_id as classId, cl.name as className, s.entry_year as entryYear, s.bind_status as bindStatus, us.real_name as realName, us.avatar as avatar, us.gender as gender from students s left join universities u on s.university_id = u.id left join sys_dept c on s.college_id = c.id left join sys_dept m on s.major_id = m.id left join sys_dept cl on s.class_id = cl.id left join user us on s.user_id = us.id
and us.real_name like concat('%', #{realName}, '%')
and s.student_no like concat('%', #{studentNo}, '%')
and s.university_id = #{universityId}
and s.college_id = #{collegeId}
and s.major_id = #{majorId}
and s.class_id = #{classId}
and s.entry_year = #{entryYear}
and s.bind_status = #{bindStatus}
order by s.id desc

